"""Imports use only generated bytes and the project's original CC0 demo."""
import hashlib
from io import BytesIO
import json
from pathlib import Path
import sys
import tempfile
from types import SimpleNamespace
import unittest
from unittest.mock import patch,Mock
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'tools/pi-tv'))
from library import Library,LibraryError
from rom_import import validate,describe,install,install_stream,metadata
import server
ROOT=Path(__file__).resolve().parents[2]

class ImportTests(unittest.TestCase):
    def setUp(self):
        self.temp=tempfile.TemporaryDirectory();self.base=Path(self.temp.name);self.mount=self.base/'library';self.mount.mkdir();self.lib=Library(self.base/'data','/library',self.mount);self.lib.configure('/library')
        self.body=(ROOT/'output/nes-demo/palette-libre.nes').read_bytes()
    def tearDown(self):self.lib.pool.shutdown();self.temp.cleanup()
    def test_atomic_import_records_metadata_and_is_idempotent(self):
        record=install(self.lib,'nes','Palette libre.nes',self.body)
        self.assertEqual(record['sha256'],hashlib.sha256(self.body).hexdigest())
        self.assertEqual(record['title'],'Palette libre');self.assertTrue(record['image'].startswith('/experience-api/v1/covers/nes/'))
        self.assertEqual((self.mount/'roms/nes/Palette libre.nes').read_bytes(),self.body)
        install(self.lib,'nes','Palette libre.nes',self.body)
        self.assertEqual(len(metadata(self.lib)),1)
        with self.assertRaises(LibraryError):install(self.lib,'nes','Palette libre.nes',self.body+b'changed')
        self.assertEqual((self.mount/'roms/nes/Palette libre.nes').read_bytes(),self.body)
    def test_invalid_console_filename_extension_and_executable(self):
        for console,name in [('nes','../x.nes'),('nes','a\\b.nes'),('nes','.x.nes'),('nes','a.html'),('../nes','x.nes'),('gba','x.nes'),('nes','a\x00.nes')]:
            with self.assertRaises(LibraryError):validate(console,name)
        for body in [b'',b'<html>not a game',b'MZ executable',b'bad nes header']:
            with self.assertRaises(LibraryError):install(self.lib,'nes','game.nes',body)
        self.assertFalse((self.mount/'roms').exists())
    def test_symlink_destination_is_refused(self):
        outside=self.base/'outside';outside.mkdir();(self.mount/'roms').symlink_to(outside)
        with self.assertRaises(OSError):install(self.lib,'nes','game.nes',self.body)
        self.assertEqual(list(outside.iterdir()),[])
    def test_header_fallback_without_inventing_a_full_title(self):
        body=bytearray(256);body[0xa0:0xac]=b'FREE DEMO\0\0\0'
        item=describe('gba','dump.gba',bytes(body));self.assertEqual(item['title'],'FREE DEMO');self.assertEqual(item['identification'],'header')
        named=describe('gba','My full title (Europe).gba',bytes(body));self.assertEqual(named['title'],'My full title (Europe)');self.assertEqual(named['internalTitle'],'FREE DEMO')
    def request(self,identity,size=None,name='Palette%20libre.nes',body=None):
        h=object.__new__(server.Handler);h.path='/v1/imports?console=nes';h.server=SimpleNamespace(library=self.lib,auth_base='http://127.0.0.1:10200');h.connection=Mock();h.headers={'Content-Length':str(size if size is not None else len(self.body)),'X-GameFlex-Filename':name};h.rfile=BytesIO(self.body if body is None else body);h.wfile=BytesIO();codes=[];h.send_response=codes.append;h.send_header=lambda *args:None;h.end_headers=lambda:None
        with patch.object(server,'verified_identity',return_value=identity):h.do_POST()
        return codes[0],json.loads(h.wfile.getvalue()),h
    def test_http_auth_size_and_success(self):
        self.assertEqual(self.request(None)[0],401)
        self.assertEqual(self.request({'username':'member','role_level':1})[0],403)
        admin={'username':'admin','role_level':0}
        code,_,handler=self.request(admin,size=0);self.assertEqual(code,411);self.assertEqual(handler.rfile.tell(),0)
        code,_,handler=self.request(admin,name='..%2Fescape.nes');self.assertEqual(code,400);self.assertEqual(handler.rfile.tell(),0)
        self.assertEqual(self.request(admin,body=b'incomplete')[0],400)
        code,data,_=self.request(admin);self.assertEqual(code,201);self.assertEqual(data['item']['title'],'Palette libre')
    def test_large_generated_import_streams_and_cleans_interrupted_upload(self):
        # Generated zero-filled test data, never a commercial ROM or download.
        size=65*1024*1024+17
        class Source:
            def __init__(self,left):self.left=left;self.max_read=0
            def read(self,count):
                self.max_read=max(self.max_read,count)
                count=min(count,self.left);self.left-=count;return b'\0'*count
        source=Source(size)
        item=install_stream(self.lib,'ps1','Generated test.iso',source,size)
        self.assertLessEqual(source.max_read,1024*1024)
        target=self.mount/'roms/ps1/Generated test.iso';self.assertEqual(target.stat().st_size,size)
        digest=hashlib.sha256()
        with target.open('rb') as f:
            for chunk in iter(lambda:f.read(1024*1024),b''):digest.update(chunk)
        self.assertEqual(item['sha256'],digest.hexdigest());self.assertEqual(item['size'],size)
        with self.assertRaises(LibraryError):install_stream(self.lib,'ps1','Interrupted.iso',Source(512),size)
        self.assertFalse((target.parent/'Interrupted.iso').exists());self.assertEqual(list(target.parent.glob('.*.part')),[])

    def test_cached_provider_artwork_is_a_fallback_without_rom_fetch(self):
        cache=self.lib.data/'freeroms';cache.mkdir(parents=True)
        (cache/'nes-P.json').write_text(json.dumps({'items':[{'title':'Palette libre (Europe)','image':'/experience-api/v1/freeroms-art/nes/palette','attribution':'Ayants droit'}]}))
        item=install(self.lib,'nes','Palette libre.nes',self.body)
        self.assertEqual(item['fallbackImage'],'/experience-api/v1/freeroms-art/nes/palette')
    def test_retry_candidates_are_bounded_and_same_console(self):
        for candidates in [['freeroms:gba:demo'],['http://example.test'],['freeroms:nes:demo']*5,'invalid']:
            with self.assertRaises(ValueError):self.lib.start('alice','freeroms:nes:first',{'candidateIds':candidates})
    def test_next_candidate_is_attempted_after_failure_with_one_final_job(self):
        from source_settings import save
        save(self.lib.data,['freeroms'])
        import time
        game={'consoleId':'nes','filename':'demo.nes','size':len(self.body),'sha256':hashlib.sha256(self.body).hexdigest()}
        with patch('freeroms.payload',side_effect=[ValueError('unavailable'),(game,self.body)]) as payload:
            job=self.lib.start('alice','freeroms:nes:first',{'candidateIds':['freeroms:nes:second']})
            for _ in range(100):
                jobs=self.lib.jobs('alice')
                if jobs[0]['status'] in ('failed','succeeded'):break
                time.sleep(.01)
        self.assertEqual(jobs[0]['status'],'succeeded');self.assertEqual(len(jobs),1)
        self.assertEqual([call.args[1] for call in payload.call_args_list],['freeroms:nes:first','freeroms:nes:second'])
